/* isgraph for OS-9/68k. * * It is in csl.l and nowhere else, and csl.l needs the trap handler that a * -qm or gcc2 link deliberately does without.  Nothing on this disk defines it * as a macro either, so it arrives at the linker as a call.  GNU ls is the * caller: system.h has ISGRAPH(c), which ls uses to decide whether a character * in a filename has to be quoted. * * The C locale definition: printing characters except the space.  Deliberately * ASCII-only -- treating the 0xA0..0xFF range as printable would make ls quote * fewer bytes than the build it replaces, and a change in what ls prints is * not something to slip in through a shim. */intisgraph(c)	int c;{	return c > 0x20 && c < 0x7f;}